// Isolated exports over actual Core; no production router or state edits.
thread_local!{static TEST_PRELUDE:RefCell<BTreeMap<u32,(Option<crate::scene_prelude::Owned>,Vec<f64>,Vec<f64>)>>=RefCell::new(BTreeMap::new());}
thread_local!{static TEST_PRELUDE_SAVES:RefCell<BTreeMap<u32,(state::Core,crate::scene_prelude::Owned)>>=RefCell::new(BTreeMap::new());}
#[no_mangle]pub extern "C" fn test_prelude_input(id:u32,words:u32)->u32{TEST_PRELUDE.with_borrow_mut(|m|{let a=m.entry(id).or_default();a.1.resize(words as usize,0.0);a.1.as_mut_ptr()as usize as u32})}
#[no_mangle]pub extern "C" fn test_prelude_install(id:u32)->u32{TEST_PRELUDE.with_borrow_mut(|m|{let Some(a)=m.get_mut(&id)else{return 1;};REGISTRY.with_borrow(|r|r.cores.get(&id).map_or(1,|c|match c.test_prelude_install(&a.0,&a.1){Ok(o)=>{a.0=Some(o);0},Err(e)=>e}))})}
#[no_mangle]pub extern "C" fn test_prelude_run(id:u32)->u32{TEST_PRELUDE.with_borrow_mut(|m|{let Some(a)=m.get_mut(&id)else{return 1;};let Some(o)=a.0.as_mut()else{return 8;};REGISTRY.with_borrow_mut(|r|r.cores.get_mut(&id).map_or(1,|c|c.test_prelude_run(o,&a.1).err().unwrap_or(0)))})}
#[no_mangle]pub extern "C" fn test_prelude_publish(id:u32)->u32{TEST_PRELUDE.with_borrow_mut(|m|{let Some(a)=m.get_mut(&id)else{return 0;};let Some(o)=&a.0 else{return 0;};REGISTRY.with_borrow(|r|{a.2=r.cores.get(&id).and_then(|c|c.test_prelude_publish(o).ok()).unwrap_or_default();a.2.as_mut_ptr()as usize as u32})})}
#[no_mangle]pub extern "C" fn test_prelude_words(id:u32)->u32{TEST_PRELUDE.with_borrow(|m|m.get(&id).map_or(0,|a|a.2.len()as u32))}
#[no_mangle]pub extern "C" fn test_prelude_save(id:u32)->u32{TEST_PRELUDE.with_borrow(|m|{let Some(a)=m.get(&id)else{return 1;};let Some(o)=&a.0 else{return 8;};REGISTRY.with_borrow(|r|{let Some(c)=r.cores.get(&id)else{return 1;};TEST_PRELUDE_SAVES.with_borrow_mut(|s|{s.insert(id,(c.test_ai_clone(),o.clone()));});0})})}
#[no_mangle]pub extern "C" fn test_prelude_restore(id:u32)->u32{TEST_PRELUDE_SAVES.with_borrow(|s|{let Some((c,o))=s.get(&id)else{return 1;};TEST_PRELUDE.with_borrow_mut(|m|{let Some(a)=m.get_mut(&id)else{return 1;};REGISTRY.with_borrow_mut(|r|{if !r.cores.contains_key(&id){return 1;}r.cores.insert(id,c.test_ai_clone());a.0=Some(o.clone());0})})})}
